// ─── İKİ KATMANLI LİMİT ─────────────────────────────────────────────────
// 1) IP başına GÜNLÜK limit: tek kullanıcının sistemi spam'lemesini engeller.
// 2) GLOBAL AYLIK limit: Apify TikTok Trending çalıştırması başına ~$0.10
//    (20 sonuç, TR proxy filtresi dahil) — TÜM kullanıcılar arasında
//    paylaşılan gerçek bütçeyi korur. IP limiti bunu KORUMAZ — 50 farklı
//    kullanıcı günde 1'er istek atsa bile toplam kota hızla biter. Apify'in
//    aylık $5 ücretsiz kredisi ~50 çalıştırmaya denk geldiği için, pay
//    bırakmak için 50 değil 45'te kesiyoruz.
const PER_IP_DAILY_LIMIT = 50;
// NOT: 'Build Search Query' 2 yerine 4 hashtag kullanmaya başladı (fyp,
// keşfet, turkiye, trendturkiye) — Apify muhtemelen her hashtag için ayrı
// ücretlendiriyor, yani çalıştırma başına maliyet ~2 katına çıkabilir. İlk
// gerçek test sonrası Apify Storage/Usage sayfasından gerçek maliyeti
// kontrol edip bu sayıyı ona göre ayarla — şimdilik ihtiyatlı başlangıç.
const GLOBAL_MONTHLY_SEARCH_LIMIT = 25;

const ip = $input.first().json.headers?.['x-forwarded-for']?.split(',')[0]?.trim() || $input.first().json.headers?.['x-real-ip'] || 'unknown';
const today = new Date().toISOString().slice(0, 10);
const monthKey = today.slice(0, 7); // 'YYYY-MM'
const ipKey = 'rl_trend_' + ip + '_' + today;
const globalKey = 'rl_trend_global_' + monthKey;

const staticData = $getWorkflowStaticData('global');
if (!staticData.rateLimits) staticData.rateLimits = {};

const ipCount = staticData.rateLimits[ipKey] || 0;
const globalCount = staticData.rateLimits[globalKey] || 0;

if (ipCount >= PER_IP_DAILY_LIMIT) {
  return [{ json: { rateLimitExceeded: true, reason: 'ip_daily' } }];
}
if (globalCount >= GLOBAL_MONTHLY_SEARCH_LIMIT) {
  return [{ json: { rateLimitExceeded: true, reason: 'global_monthly' } }];
}

staticData.rateLimits[ipKey] = ipCount + 1;
staticData.rateLimits[globalKey] = globalCount + 1;

const body = $input.first().json.body || $input.first().json;
return [{ json: { rateLimitExceeded: false, ...body } }];

// Webhook zaten 'Respond With Job ID' ile cevap verdi; burada tekrar
// HTTP yanıtı DÖNDÜRMÜYORUZ, sadece sonucu static data'ya job_id altında yazıyoruz.
const staticData = $getWorkflowStaticData('global');
const jobId = $('Create Job').first().json.jobId;
const payload = { ...$json };

if (staticData.jobs && staticData.jobs[jobId]) {
  staticData.jobs[jobId] = { status: 'completed', createdAt: staticData.jobs[jobId].createdAt, ...payload };
}
return [{ json: payload }];

const data = $input.first().json;
const staticData = $getWorkflowStaticData('global');
if (!staticData.jobs) staticData.jobs = {};
// 30 dakikadan eski job kayıtlarını temizle (static data şişmesin)
const now = Date.now();
Object.keys(staticData.jobs).forEach(id => {
  if (now - (staticData.jobs[id].createdAt || 0) > 30 * 60 * 1000) delete staticData.jobs[id];
});
const jobId = now.toString(36) + Math.random().toString(36).slice(2, 10);
staticData.jobs[jobId] = { status: 'pending', createdAt: now };
return [{ json: { ...data, jobId } }];

// Apify çağrısı başarısız olduğunda job'ı 'error' olarak işaretle.
// HTTP yanıtı zaten 202 + job_id olarak gönderildi; buradan yeni yanıt DÖNMÜYORUZ.
// İstemci polling'de status:'error' görünce kullanıcıya hata mesajı gösterir.
function extractMessage(e) {
  if (!e) return 'Bilinmeyen hata';
  if (typeof e === 'string') return e;
  if (typeof e.message === 'string' && e.message) return e.message;
  if (typeof e.error === 'string' && e.error) return e.error;
  if (e.error && typeof e.error === 'object') {
    if (typeof e.error.message === 'string' && e.error.message) return e.error.message;
    try { return JSON.stringify(e.error).slice(0, 400); } catch (_) {}
  }
  if (typeof e.statusCode !== 'undefined') return `HTTP ${e.statusCode}: ${JSON.stringify(e).slice(0, 300)}`;
  try { return JSON.stringify(e).slice(0, 400); } catch (_) { return 'Bilinmeyen hata'; }
}

const staticData = $getWorkflowStaticData('global');
const jobId = $('Create Job').first().json.jobId;
const err = $input.first().json;
const errorMessage = extractMessage(err);

if (staticData.jobs && staticData.jobs[jobId]) {
  staticData.jobs[jobId] = {
    status: 'error',
    createdAt: staticData.jobs[jobId].createdAt,
    error: errorMessage
  };
}
return [{ json: { ok: false, error: errorMessage } }];

const q = $input.first().json.query || {};
const jobId = q.jobId;
const staticData = $getWorkflowStaticData('global');
const job = (staticData.jobs || {})[jobId];
if (!job) return [{ json: { status: 'not_found' } }];
return [{ json: job }];

// Sektöre göre TikTok hashtag seçimi.
// MALİYET: Apify her hashtag'i ayrı tarar — 1 hashtag ~$0.10, 2 hashtag ~$0.20.
// Bu yüzden sektör başına EN FAZLA 2 hashtag (aşağıda MAX_HASHTAGS ile de kesiliyor).
//
// ANAHTARLAR frontend/src/lib/sektorler.ts → SEKTORLER listesindeki etiketlerle
// BİREBİR aynı olmalı (11 Eyl 2026 itibarıyla 33 sektör). Eşleşmeyen sektör
// sessizce ['keşfet']'e düşer ve arama genel içerik döndürür — 27 Ağu 2026
// sektör birleştirmesinden sonra eski anahtarlar yüzünden tam olarak bu oldu.
// SEKTORLER'e YENİ SEKTÖR EKLENİRSE BURAYA DA EKLEYİN, sonra workflow'u
// n8n'e yeniden import edip yayınlayın.
const MAX_HASHTAGS = 2;
const VARSAYILAN_HASHTAGLER = ['keşfet'];

const SEKTOR_HASHTAGLER = {
  'Dijital Ürünler / Yazılım Satışı': ['girişimci', 'onlinekurs'],
  'E-ticaret':                        ['eticaret'],
  'Eğitim / Kurs':                    ['eğitim', 'kisiselgelisim'],
  'Elektronik / Beyaz Eşya':          ['teknoloji', 'beyazeşya'],
  'Emlak / Gayrimenkul':              ['emlak', 'gayrimenkul'],
  'Evcil Hayvan / Veteriner':         ['kedi', 'veteriner'],
  'Fotoğraf / Prodüksiyon':           ['fotoğrafçı', 'videoçekimi'],
  'Giyim / Tekstil':                  ['moda', 'kombin'],
  'Güzellik / Estetik':               ['güzellik', 'kuaför'],
  'Hukuk / Danışmanlık':              ['hukuk', 'avukat'],
  'İnşaat / Mühendislik':             ['inşaat', 'mühendis'],
  'Kuyumculuk / Takı':                ['kuyumcu', 'takı'],
  'Lojistik / Taşımacılık':           ['lojistik', 'nakliye'],
  'Matbaa / Baskı':                   ['matbaa', 'baskı'],
  'Mobilite / Enerji':                ['elektrikliaraç', 'enerji'],
  'Mobilya / Ev Dekorasyonu':         ['dekorasyon', 'mobilya'],
  'Muhasebe / Finans':                ['muhasebe', 'finans'],
  'Organizasyon / Etkinlik':          ['düğün', 'organizasyon'],
  'Otomotiv':                         ['otomotiv', 'araba'],
  'Perakende / Mağaza':               ['esnaf', 'mağaza'],
  'Reklam / Pazarlama':               ['dijitalpazarlama', 'sosyalmedya'],
  'Sağlık / Klinik':                  ['sağlık', 'doktor'],
  'Sigorta / Acente':                 ['sigorta', 'kasko'],
  'Spor / Fitness':                   ['fitness', 'spor'],
  'Tarım / Hayvancılık':              ['tarım', 'çiftlik'],
  'Teknoloji / Yazılım':              ['teknoloji', 'yazılım'],
  'Tekstil Üretimi / Konfeksiyon':    ['tekstil', 'konfeksiyon'],
  'Televizyon / Medya':               ['medya', 'televizyon'],
  'Temizlik / Hizmet':                ['temizlik'],
  'Turizm / Otel':                    ['turizm', 'otel'],
  'Üretim / İmalat':                  ['üretim', 'fabrika'],
  'Yiyecek / İçecek':                 ['yemek', 'turkishfood'],
  'Diğer':                            ['esnaf'],
  'ALL':                              VARSAYILAN_HASHTAGLER,
};

const data = $input.first().json;
const sector = typeof data.sector === 'string' && data.sector.trim() ? data.sector.trim() : 'ALL';
const hashtags = (SEKTOR_HASHTAGLER[sector] || VARSAYILAN_HASHTAGLER).slice(0, MAX_HASHTAGS);
return [{ json: { ...data, hashtags } }];

const ctx = $('Build Search Query').first().json;
const items = $input.all().map(i => i.json);
const isError = items.length === 1 && items[0] && items[0].error;
const rawVideos = (!isError && items.length) ? items : [];

// Filtre 1: Türkiye pazarı için 100K eşiği — 500K Türkiye ölçeği için fazla yüksekti
const viralVideos = rawVideos.filter(v => (v.playCount || 0) >= 100000);

// Filtre 2 için 20 aday hazırla (MiniMax sonra KOBİ uyarlanabilirliğini değerlendirecek)
const videos = viralVideos
  .sort((a, b) => (b.playCount || 0) - (a.playCount || 0))
  .slice(0, 20)
  .map((v, i) => ({
    rank: i + 1,
    title: (v.text || '').slice(0, 150),
    platform: 'TikTok',
    author: v.authorMeta?.name || '',
    authorNickname: v.authorMeta?.nickName || '',
    playCount: v.playCount || 0,
    diggCount: v.diggCount || 0,
    commentCount: v.commentCount || 0,
    shareCount: v.shareCount || 0,
    webVideoUrl: v.webVideoUrl || '',
    hashtags: (v.hashtags || []).map(h => h.name || h).slice(0, 6),
    musicName: v.musicMeta?.musicName || '',
  }));

const resultData = {
  status: 'completed',
  videos,
  sector: ctx.sector || '',
  totalFound: rawVideos.length,
  totalViral: viralVideos.length,
};
return [{ json: resultData }];

const ctx = $input.first().json;
const videos = ctx.videos || [];

if (videos.length === 0) {
  return [{ json: { ...ctx, apiBodyStr: null } }];
}

const videoListStr = videos.map((v, i) =>
  `${i+1}. "${v.title.slice(0, 100)}" (@${v.authorNickname}, ${v.playCount.toLocaleString('tr-TR')} görüntüleme, ${v.hashtags.slice(0,3).join(' ')})`
).join('\n');

const sectorStr = ctx.sector && ctx.sector !== 'ALL' ? `Hedef sektör: ${ctx.sector}. Bu sektöre özellikle uygun olan formatları önceliklendir, ama diğer uyarlanabilir formatları da dahil et.` : '';
const prompt = `Aşağıdaki TikTok videolarından hangilerinde küçük işletme veya KOBİ için UYARLANABİLİR bir format var?\n\n${sectorStr}\n\nKriter: Videonun yapısı (açılış hook'u, geçiş tarzı, kapanış) sektör değiştirilse de çalışabilir mi? Sektör FARKETMEZ — penguen videosu lojistik şirketi için de çalışabilir.\n\nElenmesi gerekenler: tamamen kişisel drama/kavga, siyasi içerik, spor skoru/yorumu, çok spesifik ünlü gündemi, anlamsız random saçmalık.\n\nVideolar:\n${videoListStr}\n\nYALNIZCA uyarlanabilir videoların numaralarını virgülle döndür. Örnek: 1,3,5,7\nAçıklama yapma, sadece sayılar.`;

const apiBody = {
  model: 'MiniMax-M3',
  max_completion_tokens: 80,
  messages: [
    { role: 'system', content: 'Sen bir içerik stratejisti ve KOBİ uzmanısın. Kısa ve net yanıt ver.' },
    { role: 'user', content: prompt }
  ]
};

return [{ json: { ...ctx, apiBodyStr: JSON.stringify(apiBody) } }];

const ctx = $('Build KOBİ Filter').first().json;
const allVideos = ctx.videos || [];

let filteredVideos = allVideos;
try {
  const response = $input.first().json;
  const content = (response?.choices?.[0]?.message?.content || '').trim();
  // Parse comma-separated numbers (1-based)
  const indices = content.split(',')
    .map(s => parseInt(s.trim(), 10) - 1)
    .filter(i => !isNaN(i) && i >= 0 && i < allVideos.length);

  if (indices.length > 0) {
    filteredVideos = indices.map(i => ({ ...allVideos[i], rank: indices.indexOf(i) + 1 }));
    filteredVideos = filteredVideos.map((v, i) => ({ ...v, rank: i + 1 }));
  }
} catch(e) {
  // MiniMax hata verirse tüm videoları döndür (graceful degradation)
  filteredVideos = allVideos.slice(0, 12);
}

// Final: en fazla 12 video
filteredVideos = filteredVideos.slice(0, 12);

return [{ json: {
  status: 'completed',
  videos: filteredVideos,
  sector: ctx.sector || '',
  totalFound: ctx.totalFound,
  totalViral: ctx.totalViral,
  filteredCount: filteredVideos.length,
} }];
